             };

             assert(
                 perm.id() == pre.backing_cells.index(tail as int)
                 && perm.is_uninit()
             ) by {
                 assert(!pre.in_active_range(tail));
                 assert(pre.valid_storage_at_idx(tail));
             };
         }
     }

     transition!{
