         head: head_atomic,
         tail: tail_atomic,
         buffer: backing_cells_vec,
     };
     let queue_arc = Arc::new(queue);
     let prod = Producer::<T> {
         queue: queue_arc.clone(),
         tail: 0,
         producer: Tracked(producer_token),
     };
     let cons = Consumer::<T> { queue: queue_arc, head: 0, consumer: Tracked(consumer_token) };
