 impl<T> Producer<T> {
     fn enqueue(&mut self, t: T)
         requires
             old(self).wf(),
         ensures
             final(self).wf(),
     {
         loop
             invariant
                 self.wf(),
         {
             let queue = &*self.queue;
             let len = queue.buffer.len();
             assert(0 <= self.tail && self.tail < len);
             let next_tail = if self.tail + 1 == len {
